    def __init__(self, *, signatures: "typing.List[MultisigMemberSignature]", bitmap: "int", committee: "MultisigCommittee"):
        self.signatures = signatures
        self.bitmap = bitmap
        self.committee = committee

    def __str__(self):
        return "MultisigAggregatedSignature(signatures={}, bitmap={}, committee={})".format(self.signatures, self.bitmap, self.committee)

    def __eq__(self, other):
        if self.signatures != other.signatures:
            return False
        if self.bitmap != other.bitmap:
            return False
        if self.committee != other.committee:
            return False
        return True

