class PasskeyAuthenticator:
    """
    A passkey authenticator.

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    passkey-bcs = bytes               ; where the contents of the bytes are
    ; defined by <passkey>
    passkey     = passkey-flag
    bytes               ; passkey authenticator data
    client-data-json    ; valid json
    simple-signature    ; required to be a secp256r1 signature

    client-data-json = string ; valid json
    ```

    See [CollectedClientData](https://www.w3.org/TR/webauthn-2/#dictdef-collectedclientdata) for
    the required json-schema for the `client-data-json` rule. In addition, IOTA
    currently requires that the `CollectedClientData.type` field is required to
    be `webauthn.get`.

    Note: Due to historical reasons, signatures are serialized slightly
    different from the majority of the types in IOTA. In particular if a
    signature is ever embedded in another structure it generally is serialized
    as `bytes` meaning it has a length prefix that defines the length of
    the completely serialized signature.
    """

    public_key: "Secp256r1PublicKey"
    """
    The secp256r1 public key for this passkey.
    """

    signature: "Secp256r1Signature"
    """
    The secp256r1 signature from the passkey.
    """

    challenge: "bytes"
    """
    Parsed base64url decoded challenge bytes from
    `client_data_json.challenge`.
    """

    authenticator_data: "bytes"
    """
    Opaque authenticator data for this passkey signature.

    See [Authenticator Data](https://www.w3.org/TR/webauthn-2/#sctn-authenticator-data) for
    more information on this field.
    """

    client_data_json: "str"
    """
    Structured, unparsed, JSON for this passkey signature.

    See [CollectedClientData](https://www.w3.org/TR/webauthn-2/#dictdef-collectedclientdata)
    for more information on this field.
    """

    def __init__(self, *, public_key: "Secp256r1PublicKey", signature: "Secp256r1Signature", challenge: "bytes", authenticator_data: "bytes", client_data_json: "str"):
        self.public_key = public_key
        self.signature = signature
        self.challenge = challenge
        self.authenticator_data = authenticator_data
        self.client_data_json = client_data_json

    def __str__(self):
        return "PasskeyAuthenticator(public_key={}, signature={}, challenge={}, authenticator_data={}, client_data_json={})".format(self.public_key, self.signature, self.challenge, self.authenticator_data, self.client_data_json)

    def __eq__(self, other):
        if self.public_key != other.public_key:
            return False
        if self.signature != other.signature:
            return False
        if self.challenge != other.challenge:
            return False
        if self.authenticator_data != other.authenticator_data:
            return False
        if self.client_data_json != other.client_data_json:
            return False
        return True

