class ZkLoginPublicIdentifier:
    """
    Public Key equivalent for Zklogin authenticators

    A `ZkLoginPublicIdentifier` is the equivalent of a public key for other
    account authenticators, and contains the information required to derive the
    onchain account [`Address`] for a Zklogin authenticator.

    ## Note

    Due to a historical bug that was introduced in the IOTA Typescript SDK when
    the zklogin authenticator was first introduced, there are now possibly two
    "valid" addresses for each zklogin authenticator depending on the
    bit-pattern of the `address_seed` value.

    The original bug incorrectly derived a zklogin's address by stripping any
    leading zero-bytes that could have been present in the 32-byte length
    `address_seed` value prior to hashing, leading to a different derived
    address. This incorrectly derived address was presented to users of various
    wallets, leading them to sending funds to these addresses that they couldn't
    access. Instead of letting these users lose any assets that were sent to
    these addresses, the IOTA network decided to change the protocol to allow
    for a zklogin authenticator who's `address_seed` value had leading
    zero-bytes be authorized to sign for both the addresses derived from both
    the unpadded and padded `address_seed` value.

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    zklogin-public-identifier-bcs = bytes ; where the contents are defined by
    ; <zklogin-public-identifier>

    zklogin-public-identifier = zklogin-public-identifier-iss
    address-seed

    zklogin-public-identifier-unpadded = zklogin-public-identifier-iss
    address-seed-unpadded

    ; The iss, or issuer, is a utf8 string that is less than 255 bytes long
    ; and is serialized with the iss's length in bytes as a u8 followed by
    ; the bytes of the iss
    zklogin-public-identifier-iss = u8 *255(OCTET)

    ; A Bn254FieldElement serialized as a 32-byte big-endian value
    address-seed = 32(OCTET)

    ; A Bn254FieldElement serialized as a 32-byte big-endian value
    ; with any leading zero bytes stripped
    address-seed-unpadded = %x00 / %x01-ff *31(OCTET)
    ```

    [`Address`]: crate::Address
    """

    iss: "str"
    address_seed: "Bn254FieldElement"
    def __init__(self, *, iss: "str", address_seed: "Bn254FieldElement"):
        self.iss = iss
        self.address_seed = address_seed

    def __str__(self):
        return "ZkLoginPublicIdentifier(iss={}, address_seed={})".format(self.iss, self.address_seed)

    def __eq__(self, other):
        if self.iss != other.iss:
            return False
        if self.address_seed != other.address_seed:
            return False
        return True

class _UniffiConverterTypeZkLoginPublicIdentifier(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return ZkLoginPublicIdentifier(
            iss=_UniffiConverterString.read(buf),
            address_seed=_UniffiConverterTypeBn254FieldElement.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiConverterString.check_lower(value.iss)
        _UniffiConverterTypeBn254FieldElement.check_lower(value.address_seed)

    @staticmethod
    def write(value, buf):
        _UniffiConverterString.write(value.iss, buf)
        _UniffiConverterTypeBn254FieldElement.write(value.address_seed, buf)





class Argument:
    """
    An argument to a programmable transaction command

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    argument    =  argument-gas
    =/ argument-input
    =/ argument-result
    =/ argument-nested-result

    argument-gas            = %x00
    argument-input          = %x01 u16
    argument-result         = %x02 u16
    argument-nested-result  = %x03 u16 u16
    ```
    """

    def __init__(self):
        raise RuntimeError("Argument cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class GAS:
        """
        The gas coin. The gas coin can only be used by-ref, except for with
        `TransferObjects`, which can use it by-value.
        """


        def __init__(self,):
            pass

        def __str__(self):
            return "Argument.GAS()".format()

        def __eq__(self, other):
            if not other.is_GAS():
                return False
            return True
    
    class INPUT:
        """
        One of the input objects or primitive values (from
        `ProgrammableTransaction` inputs)
        """

        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Argument.INPUT{self._values!r}"

        def __eq__(self, other):
            if not other.is_INPUT():
                return False
            return self._values == other._values
    class RESULT:
        """
        The result of another command (from `ProgrammableTransaction` commands)
        """

        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Argument.RESULT{self._values!r}"

        def __eq__(self, other):
            if not other.is_RESULT():
                return False
            return self._values == other._values
    class NESTED_RESULT:
        """
        Like a `Result` but it accesses a nested result. Currently, the only
        usage of this is to access a value from a Move call with multiple
        return values.
        """

        def __init__(self, *values):
            if len(values) != 2:
                raise TypeError(f"Expected 2 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Argument.NESTED_RESULT{self._values!r}"

        def __eq__(self, other):
            if not other.is_NESTED_RESULT():
                return False
            return self._values == other._values
    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_GAS(self) -> bool:
        return isinstance(self, Argument.GAS)
    def is_gas(self) -> bool:
        return isinstance(self, Argument.GAS)
    def is_INPUT(self) -> bool:
        return isinstance(self, Argument.INPUT)
    def is_input(self) -> bool:
        return isinstance(self, Argument.INPUT)
    def is_RESULT(self) -> bool:
        return isinstance(self, Argument.RESULT)
    def is_result(self) -> bool:
        return isinstance(self, Argument.RESULT)
    def is_NESTED_RESULT(self) -> bool:
        return isinstance(self, Argument.NESTED_RESULT)
    def is_nested_result(self) -> bool:
        return isinstance(self, Argument.NESTED_RESULT)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
Argument.GAS = type("Argument.GAS", (Argument.GAS, Argument,), {})  # type: ignore
Argument.INPUT = type("Argument.INPUT", (Argument.INPUT, Argument,), {})  # type: ignore
Argument.RESULT = type("Argument.RESULT", (Argument.RESULT, Argument,), {})  # type: ignore
Argument.NESTED_RESULT = type("Argument.NESTED_RESULT", (Argument.NESTED_RESULT, Argument,), {})  # type: ignore




class _UniffiConverterTypeArgument(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Argument.GAS(
            )
        if variant == 2:
            return Argument.INPUT(
                _UniffiConverterUInt16.read(buf),
            )
        if variant == 3:
            return Argument.RESULT(
                _UniffiConverterUInt16.read(buf),
            )
        if variant == 4:
            return Argument.NESTED_RESULT(
                _UniffiConverterUInt16.read(buf),
                _UniffiConverterUInt16.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_GAS():
            return
        if value.is_INPUT():
            _UniffiConverterUInt16.check_lower(value._values[0])
            return
        if value.is_RESULT():
            _UniffiConverterUInt16.check_lower(value._values[0])
            return
        if value.is_NESTED_RESULT():
            _UniffiConverterUInt16.check_lower(value._values[0])
            _UniffiConverterUInt16.check_lower(value._values[1])
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_GAS():
            buf.write_i32(1)
        if value.is_INPUT():
            buf.write_i32(2)
            _UniffiConverterUInt16.write(value._values[0], buf)
        if value.is_RESULT():
            buf.write_i32(3)
            _UniffiConverterUInt16.write(value._values[0], buf)
        if value.is_NESTED_RESULT():
            buf.write_i32(4)
            _UniffiConverterUInt16.write(value._values[0], buf)
            _UniffiConverterUInt16.write(value._values[1], buf)







