    def is_PUBLISH(self) -> bool:
        return isinstance(self, Command.PUBLISH)
    def is_publish(self) -> bool:
        return isinstance(self, Command.PUBLISH)
    def is_MAKE_MOVE_VECTOR(self) -> bool:
        return isinstance(self, Command.MAKE_MOVE_VECTOR)
    def is_make_move_vector(self) -> bool:
        return isinstance(self, Command.MAKE_MOVE_VECTOR)
    def is_UPGRADE(self) -> bool:
        return isinstance(self, Command.UPGRADE)
    def is_upgrade(self) -> bool:
        return isinstance(self, Command.UPGRADE)
    

