Command.TRANSFER_OBJECTS = type("Command.TRANSFER_OBJECTS", (Command.TRANSFER_OBJECTS, Command,), {})  # type: ignore
Command.SPLIT_COINS = type("Command.SPLIT_COINS", (Command.SPLIT_COINS, Command,), {})  # type: ignore
