    """
    Key for an execution time observation

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    execution-time-observation-key  =  %x00 move-entry-point
    =/ %x01 ; transfer-objects
    =/ %x02 ; split-coins
    =/ %x03 ; merge-coins
    =/ %x04 ; publish
    =/ %x05 ; make-move-vec
    =/ %x06 ; upgrade

    move-entry-point = object-id string string (vec type-tag)
    ```
    """

    def __init__(self):
        raise RuntimeError("ExecutionTimeObservationKey cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class MOVE_ENTRY_POINT:
        package: "ObjectId"
        """
        The package containing the module and function.
        """

