class SimpleSignature:
    """
    A basic signature

    This enumeration defines the set of simple or basic signature schemes
    supported by IOTA. Most signature schemes supported by IOTA end up
    comprising of a at least one simple signature scheme.

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    simple-signature-bcs = bytes ; where the contents of the bytes are defined by <simple-signature>
    simple-signature = (ed25519-flag ed25519-signature ed25519-public-key) /
    (secp256k1-flag secp256k1-signature secp256k1-public-key) /
    (secp256r1-flag secp256r1-signature secp256r1-public-key)
    ```

    Note: Due to historical reasons, signatures are serialized slightly
    different from the majority of the types in IOTA. In particular if a
    signature is ever embedded in another structure it generally is serialized
    as `bytes` meaning it has a length prefix that defines the length of
    the completely serialized signature.
    """

    def __init__(self):
        raise RuntimeError("SimpleSignature cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class ED25519:
        signature: "Ed25519Signature"
        public_key: "Ed25519PublicKey"

        def __init__(self,signature: "Ed25519Signature", public_key: "Ed25519PublicKey"):
            self.signature = signature
            self.public_key = public_key

        def __str__(self):
            return "SimpleSignature.ED25519(signature={}, public_key={})".format(self.signature, self.public_key)

        def __eq__(self, other):
            if not other.is_ED25519():
                return False
            if self.signature != other.signature:
                return False
            if self.public_key != other.public_key:
                return False
            return True
    
    class SECP256K1:
        signature: "Secp256k1Signature"
        public_key: "Secp256k1PublicKey"

        def __init__(self,signature: "Secp256k1Signature", public_key: "Secp256k1PublicKey"):
            self.signature = signature
            self.public_key = public_key

        def __str__(self):
            return "SimpleSignature.SECP256K1(signature={}, public_key={})".format(self.signature, self.public_key)

        def __eq__(self, other):
            if not other.is_SECP256K1():
                return False
            if self.signature != other.signature:
                return False
            if self.public_key != other.public_key:
                return False
            return True
    
    class SECP256R1:
        signature: "Secp256r1Signature"
        public_key: "Secp256r1PublicKey"

        def __init__(self,signature: "Secp256r1Signature", public_key: "Secp256r1PublicKey"):
            self.signature = signature
            self.public_key = public_key

        def __str__(self):
            return "SimpleSignature.SECP256R1(signature={}, public_key={})".format(self.signature, self.public_key)

        def __eq__(self, other):
            if not other.is_SECP256R1():
                return False
            if self.signature != other.signature:
                return False
            if self.public_key != other.public_key:
                return False
            return True
    
    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_ED25519(self) -> bool:
        return isinstance(self, SimpleSignature.ED25519)
    def is_ed25519(self) -> bool:
        return isinstance(self, SimpleSignature.ED25519)
    def is_SECP256K1(self) -> bool:
        return isinstance(self, SimpleSignature.SECP256K1)
    def is_secp256k1(self) -> bool:
        return isinstance(self, SimpleSignature.SECP256K1)
    def is_SECP256R1(self) -> bool:
        return isinstance(self, SimpleSignature.SECP256R1)
    def is_secp256r1(self) -> bool:
        return isinstance(self, SimpleSignature.SECP256R1)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
SimpleSignature.ED25519 = type("SimpleSignature.ED25519", (SimpleSignature.ED25519, SimpleSignature,), {})  # type: ignore
SimpleSignature.SECP256K1 = type("SimpleSignature.SECP256K1", (SimpleSignature.SECP256K1, SimpleSignature,), {})  # type: ignore
SimpleSignature.SECP256R1 = type("SimpleSignature.SECP256R1", (SimpleSignature.SECP256R1, SimpleSignature,), {})  # type: ignore




